参考实现                                                                 PYTHON

import json, sys

TOOLS = [{
    "name": "get_order",
    "description": "按订单号查物流状态；只读，不修改订单",
    "inputSchema": {"type": "object",
                    "properties": {"order_id": {"type": "string"}},
                    "required": ["order_id"]},
}]

def call_tool(name, args):
    if name != "get_order":
        return {"content": [{"type": "text", "text": f"未知工具：{name}"}], "isErro
r": True}
    oid = args.get("order_id")
    if not isinstance(oid, str) or not oid:
        return {"content": [{"type": "text", "text": "order_id 必须是非空字符串"}], "i
sError": True}
    return {"content": [{"type": "text", "text": json.dumps({"order_id": oid, "statu
s": "已发货"}, ensure_ascii=False)}]}

def handle(req):
    mid, rid = req.get("method"), req.get("id")
    if mid == "initialize":                      # 1 协议协商：版本 + 能力
        return {"jsonrpc": "2.0", "id": rid, "result": {
            "protocolVersion": "2025-06-18",
            "capabilities": {"tools": {}},
            "serverInfo": {"name": "order-mcp", "version": "0.1"}}}
    if mid == "tools/list":                      # 2 让模型知道有什么工具
        return {"jsonrpc": "2.0", "id": rid, "result": {"tools": TOOLS}}
    if mid == "tools/call":                      # 3 调用：入参校验 + isError 语义
        p = req.get("params") or {}
        return {"jsonrpc": "2.0", "id": rid,
                "result": call_tool(p.get("name"), p.get("arguments") or {})}
    if rid is None:                              # notification（如 notifications/in
itialized）不回包
        return None
    return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32601, "message": "Metho
d not found"}}

for line in sys.stdin:                           # stdio：一行一条 JSON-RPC
    line = line.strip()
    if not line:
        continue
    resp = handle(json.loads(line))
    if resp:
        sys.stdout.write(json.dumps(resp, ensure_ascii=False) + "\n")
        sys.stdout.flush()

三件套             initialize → tools/list → tools/call，顺序不能换。客户端在握手阶段拿不
        到能力声明，后面全会失败。
传输层          stdio 给本机进程用，比如桌面客户端和 CLI；远程用 Streamable
          HTTP，它是 2025 年 3 月之后取代旧双通道的方案。
错误语义    协议错误走 error，例如方法不存在、参数不合法；工具执行失败走 result
        里的 isError。两者混用，客户端会误判成连接坏了。
stdout 纪律   一行一条消息，只放协议内容。调试用 print 会把 JSON 流切断，日志必
        须走 stderr。

生命周期          initialize → 初始化通知 → 正常调用 → shutdown。漏发初始化通知，多
        数客户端会一直认为服务还没就绪。

 易错警示　跳过 initialize 直接 tools/call，客户端报协议错；tools/list 里 schema 写成
 any，模型填进来的参数全靠猜。

追问 · 变式
Q MCP 和直接写 function calling 有什么区别？— 工具定义与执行从「应用内函数」变成

「独立进程服务」，可以跨应用复用、按租户下发不同工具集；代价是多一层进程与协议。

Q server 要不要做鉴权？— 本地 stdio 靠进程权限；远程必须 bearer / OAuth，并按租户
裁剪 tools/list，否则越权查询就发生在工具层。

Q 内网为什么偏爱 stdio？— 不起端口、不出网、权限跟进程走，审计只看一个可执行文
件；代价是不能跨机共享，需要每台部署。

Q 工具写操作怎么管？— 写操作单独列名单 + 二次确认 + 幂等键；MCP 只负责传参，权限

判断不能交给模型。



5.6   中档     前端最小流式界面
 考点EventSource 只发 GET、不能带自定义头，这两条限制决定了鉴权怎么做——走
  cookie 或短期 token，绝不能把长期 key 放进 URL。渲染层要按 id 去重加节流，每来一
 个 token 就 setState 会直接掉帧；组件卸载时必须 close，否则连接会一直挂着，越积越
 多。

 结论EventSource 只 GET、按 id 去重、帧级节流、卸载必 close。

 参考实现                                                                      TSX

 import { useEffect, useRef, useState } from "react";

 export default function StreamAnswer({ sessionId, token }) {
   const [text, setText] = useState("");
   const [state, setState] = useState("connecting");
   const lastId = useRef(0);
   const buf = useRef(""), raf = useRef(0);
   useEffect(() => {
     // EventSource 不能带 Authorization 头：用 query 传短期 token，或依赖 cookie
     const es = new EventSource(`/api/chat/stream?session=${sessionId}&t=${token}`);

     es.onopen = () => setState("streaming");
     es.onmessage = (e) => {
       const id = Number(e.lastEventId || 0);
       if (id && id <= lastId.current) return;       // 1 重连补发：按 id 去重
       if (id) lastId.current = id;
       buf.current += e.data;
       if (!raf.current) {                            // 2 帧级节流，别每 token 一次 set
 State
         raf.current = requestAnimationFrame(() => {
           raf.current = 0;
           setText(buf.current);
         });
       }
     };

es.addEventListener("done", () => { setState("done"); es.close(); });
     es.onerror = () => {
       setState("reconnecting");                      // 3 浏览器自动重连并带 Last-Event
 -ID
     };

     return () => {                                   // 4 卸载清理，否则重复挂载会叠加连
 接
       if (raf.current) cancelAnimationFrame(raf.current);
       es.close();
     };
   }, [sessionId, token]);

   return <div className={`ans ${state}`}>{text}{state === "streaming" && <i classNam
 e="caret" />}</div>;
 }

去重与续传   服务端带 id，浏览器自动补 Last-Event-ID；前端按 id 丢弃重复片段，
        否则每次重连都会重复一段文字。
渲染性能    每个 token 触发一次 setState 会掉帧。用 requestAnimationFrame 合
        批，一帧刷一次就够了。
清理与状态   卸载要 close，防止连接泄漏；状态机分 connecting、streaming、
               reconnecting、done 四态，界面才不会乱跳。

 易错警示　把长期 key 拼进 EventSource 的 URL，日志和浏览器历史各留一份；渲染时
 不锁滚动，用户往下翻被拽回顶部。

追问 · 变式
Q 要 POST 怎么办？— EventSource 做不到，改用 fetch + ReadableStream 手动解析
SSE 帧；代价是重连要自己实现。

Q 重连会不会重复渲染整段？— 按 id 去重并把已渲染长度记下来即可；服务端从 last+1 开

始发是最省事的做法。

Q 首字慢是前端问题吗？— 查后端 TTFT：system 与历史跑完才开流，前端不背模型延迟。


本章小结

  服务端的判断可归结为一句：把不确定收敛到一处。会话状态收敛到一处存储，超时收敛
到一个配置，异常收敛到一个处理器，限流收敛到一个中间件。收敛之后，出错才有唯一排查
入口。

  流式接口需补充一点：断开是常态而非异常。用户切走、网络抖动、代理超时都会断开，
代码必须写明断开后的动作：落终态、存断点、释放资源，三项缺一不可。

def timed(fn):                                   # 1 计时
     @wraps(fn)
     def wrapper(*a, **kw):
         t0 = time.perf_counter()
         try:
             return fn(*a, **kw)
         finally:                                 # 异常也要记耗时
             logging.info("%s cost=%.2fms", fn.__name__, (time.perf_counter() - t0) *
 1000)
     return wrapper

 def retry(times=3, exc=(Exception,), backoff=0.5):   # 2 带参重试
     if times < 1:
         raise ValueError("times 必须 >= 1")           # 装饰时就校验参数
     def deco(fn):
         @wraps(fn)
         def wrapper(*a, **kw):
             for i in range(1, times + 1):
                 try:
                     return fn(*a, **kw)
                 except exc:
                     if i == times:
                         raise
                     time.sleep(backoff * 2 ** (i - 1))
         return wrapper
     return deco

 def memo(maxsize=128):                            # 3 缓存
     def deco(fn):
         cache = {}
         @wraps(fn)
         def wrapper(*a, **kw):
             k = (a, tuple(sorted(kw.items())))     # kwargs 必须先归一化
             if k not in cache:
                 if len(cache) >= maxsize:
                     cache.pop(next(iter(cache)))   # 简单 FIFO 淘汰
                 cache[k] = fn(*a, **kw)
             return cache[k]
         wrapper.cache_clear = cache.clear          # 暴露清理入口
         return wrapper
     return deco

 wraps     不加 wraps，名字全变成 wrapper，日志、缓存键、框架注册一起乱。它
        还会带上 __wrapped__，调试时能找到原函数。
提前校验    装饰时就校验参数，比如 times 小于 1 直接抛。比等到第一次调用才炸，
        早了整整一个部署周期。
缓存键              list 和 dict 不可哈希，要转 tuple；kwargs 必须排序。不排序，两个等价
        的调用会被当成两个键。
内存      无界 dict 会 OOM，必须有 maxsize 加淘汰。严谨一点用 OrderedDict
        做 LRU，思路见 6.5。

 易错警示　漏掉最外层，带参装饰就 TypeError；不加 wraps，日志和 traceback 里全是
 wrapper，出了错找不到原函数。

