 @Bean
 RestClient llm(RestClient.Builder b) {
     var f = new SimpleClientHttpRequestFactory();
     f.setConnectTimeout(3_000);
     f.setReadTimeout(60_000);              // 流式必须单独放宽读超时
     return b.baseUrl("http://llm:8000").requestFactory(f).build();
 }

 @GetMapping(value = "/chat", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
 public Flux<ServerSentEvent<String>> chat(@RequestParam String q) {
     return llm.post().uri("/v1/chat").bodyValue(payload(q))
         .retrieve().bodyToFlux(String.class)
         .map(t -> ServerSentEvent.builder(t).build())
         .mergeWith(heartbeat(20))          // 20s 心跳：防代理断连
         .timeout(Duration.ofSeconds(90));  // 整体兜底，不让请求挂死
 }

 // 重试只配幂等请求；写操作配重试等于制造重复扣款
 Retry retry = Retry.of("llm", RetryConfig.custom()
         .maxAttempts(3).waitDuration(Duration.ofMillis(800)).build());

面试口径：被问「Java 怎么接大模型」，答一句话定位——「Java 做入口、鉴权、限流、审
计，Python 做编排与推理」，再给 SSE 与重试两条细节。


    19.5   Java 与 Python 的分工边界 · 什么活该谁干


双语言项目最怕两边都写一半，最后谁也不敢改


  判断标准只有一条：这个模块的变更频率与依赖生态。变更快、依赖 AI 库的放 Python；

变更慢、要求稳、要和客户系统贴合的放 Java。边界一旦定下，用 HTTP 或消息队列连起

来，不要两边共享数据库表。

